ROW_SRC_TOP = 389.812
ROW_SRC_BOT = 447.7129
ROW_SRC_MITER = 0.8067


def _map_y(y, y_top, y_bot):
    if abs(y - ROW_SRC_TOP) < 0.05:
        return y_top
    if abs(y - ROW_SRC_BOT) < 0.05:
        return y_bot
    if abs(y - (ROW_SRC_BOT - ROW_SRC_MITER)) < 0.05:
        return y_bot - ROW_SRC_MITER
    if abs(y - (ROW_SRC_TOP + ROW_SRC_MITER)) < 0.05:
        return y_top + ROW_SRC_MITER
    t = (y - ROW_SRC_TOP) / (ROW_SRC_BOT - ROW_SRC_TOP)
    return y_top + t * (y_bot - y_top)


def _map_op(op, y_top, y_bot):
    kind = op[0]
    if kind == "re":
        return ("re", op[1], _map_y(op[2], y_top, y_bot), op[3], _map_y(op[4], y_top, y_bot))
    if kind == "l":
        return ("l", op[1], _map_y(op[2], y_top, y_bot), op[3], _map_y(op[4], y_top, y_bot))
    raise ValueError(kind)


def row_ops(y_top, y_bot):
    if abs(y_top - ROW_SRC_TOP) < 0.02 and abs(y_bot - ROW_SRC_BOT) < 0.02:
        return ROW_OPS
    return tuple(tuple(_map_op(op, y_top, y_bot) for op in ops) for ops in ROW_OPS)
